module "eventbridge" {
  source = "terraform-aws-modules/eventbridge/aws"

  tags     = var.tags
  bus_name = var.custom_actions_config.event_bus_name

  rules = {
    security_hub_notify = {
      description = "Send Security Hub custom action events to SNS"

      event_pattern = jsonencode({
        source = [
          "aws.securityhub"
        ]

        detail-type = [
          "Security Hub Findings - Custom Action"
        ]

        resources = [
          aws_securityhub_action_target.notify.arn
        ]
      })
    }
  }

  targets = {
    security_hub_notify = [
      {
        name = "send-security-finding-to-sns"
        arn  = aws_sns_topic.security_alerts.arn
      }
    ]
  }

